WITH w(label,a,b) AS (VALUES ('current30','2026-09-27T16:00:00Z','2026-10-27T16:00:00Z'),('previous30','2026-08-28T16:00:00Z','2026-09-27T16:00:00Z'),('last7','2026-10-20T16:00:00Z','2026-10-27T16:00:00Z')) SELECT label,(SELECT COUNT(*) FROM players WHERE created_at>=a AND created_at<b) AS new_browser_players,(SELECT COUNT(*) FROM run_tickets WHERE started_at>=a AND started_at<b) AS tickets,(SELECT COUNT(DISTINCT player_id) FROM run_tickets WHERE started_at>=a AND started_at<b) AS active_players,(SELECT COUNT(*) FROM score_submissions WHERE submitted_at>=a AND submitted_at<b) AS scores,(SELECT COUNT(DISTINCT player_id) FROM score_submissions WHERE submitted_at>=a AND submitted_at<b) AS submitting_players FROM w;
SELECT date(started_at,'+8 hours') AS day,COUNT(*) AS tickets,COUNT(DISTINCT player_id) AS active_players FROM run_tickets WHERE started_at>='2026-09-27T16:00:00Z' AND started_at<'2026-10-27T16:00:00Z' GROUP BY day ORDER BY day;
SELECT COUNT(*) AS players, SUM(days>1) AS repeat_day_players,MAX(days) AS max_active_days FROM (SELECT player_id,COUNT(DISTINCT date(started_at,'+8 hours')) AS days FROM run_tickets WHERE started_at>='2026-09-27T16:00:00Z' AND started_at<'2026-10-27T16:00:00Z' GROUP BY player_id);
SELECT COUNT(*) AS scores,ROUND(AVG(elapsed_ms)/1000,1) AS avg_seconds,SUM(elapsed_ms)/3600000.0 AS total_hours FROM score_submissions WHERE submitted_at>='2026-09-27T16:00:00Z' AND submitted_at<'2026-10-27T16:00:00Z';